public class Main {
    enum Status { NEW, PAID, SHIPPED }

    record Order(String id, double amount, Status status) {
        Order {
            if (amount < 0) throw new IllegalArgumentException("amount");
        }
    }

    public static void main(String[] args) {
        Order o = new Order("A-1", 499.0, Status.PAID);
        System.out.println(o);
        System.out.println(switch (o.status()) {
            case NEW -> "waiting for payment";
            case PAID -> "packing";
            case SHIPPED -> "on the way";
        });
        try {
            new Order("A-2", -1, Status.NEW);
        } catch (IllegalArgumentException e) {
            System.out.println("rejected: " + e.getMessage());
        }
    }
}

public class Main {
    sealed interface Shape permits Circle, Square {}
    record Circle(double r) implements Shape {}
    record Square(double side) implements Shape {}

    static double area(Shape s) {
        if (s instanceof Circle c) return Math.PI * c.r() * c.r();
        Square sq = (Square) s;
        return sq.side() * sq.side();
    }

    static class Formatter {
        static String money(double v) { return String.format("%.2f", v); }
    }

    public static void main(String[] args) {
        Shape[] shapes = { new Circle(1), new Square(2) };
        for (Shape s : shapes) System.out.println(Formatter.money(area(s)));
    }
}

